// client/src/pages/TrainingPage.js
import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import TrainingUploader from '../components/training/TrainingUploader';
import TrainingComplianceDisplay from '../components/training/TrainingComplianceDisplay';
import SingleRecordForm from '../components/training/SingleRecordForm';
import { 
  fetchTrainingData, 
  saveTrainingData, 
  archiveTrainingRecord,
  unarchiveTrainingRecord
} from '../components/services/trainingApi';

export default function TrainingPage() {
  const [trainingRecords, setTrainingRecords] = useState([]);
  const [trainingComplianceData, setTrainingComplianceData] = useState(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [saveResponse, setSaveResponse] = useState(null);
  const [showUploader, setShowUploader] = useState(false);
  const [showAddForm, setShowAddForm] = useState(false);
  const [filter, setFilter] = useState('');
  const [filterBy, setFilterBy] = useState('employee');
  const [showArchived, setShowArchived] = useState(false);
  
  // Load training data on component mount and when showArchived changes
  useEffect(() => {
    loadTrainingData();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [showArchived]);
  
  // Function to load training data
  const loadTrainingData = async () => {
    try {
      setLoading(true);
      const data = await fetchTrainingData(true, showArchived); // Force refresh, pass showArchived flag
      
      // Process and store compliance data for the dashboard
      if (data.records && Array.isArray(data.records)) {
        setTrainingRecords(data.records);
        const complianceData = generateComplianceData(data.records);
        setTrainingComplianceData(complianceData);
      } else if (Array.isArray(data)) {
        setTrainingRecords(data);
        const complianceData = generateComplianceData(data);
        setTrainingComplianceData(complianceData);
      } else {
        console.log('No valid training data received:', data);
        setTrainingRecords([]);
      }
      
      setError(null);
    } catch (err) {
      console.error('Error loading training data:', err);
      setError('Failed to load training data: ' + (err.message || 'Unknown error'));
      setTrainingRecords([]);
      setTrainingComplianceData(null);
    } finally {
      setLoading(false);
    }
  };
  
  // Generate compliance data from records
  const generateComplianceData = (records) => {
    if (!records || !Array.isArray(records) || records.length === 0) {
      return null;
    }
    
    const total = records.length;
    const completed = records.filter(r => r.status === 'Completed').length;
    const expired = records.filter(r => r.status === 'Expired').length;
    
    // Find upcoming renewals (records with expiry dates in next 30 days)
    const today = new Date();
    const thirtyDaysFromNow = new Date();
    thirtyDaysFromNow.setDate(today.getDate() + 30);
    
    const upcomingRenewals = records
      .filter(record => {
        if (!record.expiryDate) return false;
        
        const expiryDate = new Date(record.expiryDate);
        return !isNaN(expiryDate.getTime()) && 
               expiryDate > today && 
               expiryDate <= thirtyDaysFromNow;
      })
      .map(record => {
        const expiryDate = new Date(record.expiryDate);
        const daysRemaining = Math.ceil((expiryDate - today) / (1000 * 60 * 60 * 24));
        
        return {
          employee: record.employee,
          trainingType: record.courseTitle || record.courseType || 'Training',
          expirationDate: expiryDate,
          daysRemaining
        };
      });
    
    // Sort by days remaining (ascending)
    upcomingRenewals.sort((a, b) => a.daysRemaining - b.daysRemaining);
    
    return {
      compliance: total > 0 ? (completed / total) * 100 : 0,
      stats: {
        total,
        completed,
        expired,
        upcoming: upcomingRenewals.length
      },
      upcomingRenewals,
      records
    };
  };
  
  // Handle data from CSV upload
  const onDataProcessed = async (data) => {
    try {
      // Ensure we have data to save
      if (!data || !Array.isArray(data) || data.length === 0) {
        throw new Error('No valid training data to save');
      }
      
      console.log('Processing training data before API save:');
      
      // Generate compliance data
      const complianceData = generateComplianceData(data);
      
      // Create a properly structured payload for the API
      const payload = {
        records: data,
        ...complianceData
      };
      
      console.log(payload);
      
      // Save the data to the API
      const serverResponse = await saveTrainingData(payload);
      
      // Display success message
      setSaveResponse({
        success: true,
        message: `Successfully saved ${data.length} training records${serverResponse.local ? ' to local storage (server unavailable)' : ''}`,
      });
      
      // Reload the data to show the new records
      loadTrainingData();
      
      // Hide the uploader after successful save
      setTimeout(() => {
        setShowUploader(false);
      }, 3000);
    } catch (err) {
      console.error('Error saving training data:', err);
      setSaveResponse({
        success: false,
        message: `Error: ${err.message || 'Unknown error'}`,
      });
    }
  };
  
  // Handle new single record submission
  const handleAddRecord = async (record) => {
    try {
      // Add the record to existing training data
      const updatedRecords = [...trainingRecords, record];
      
      // Generate updated compliance data
      const complianceData = generateComplianceData(updatedRecords);
      
      // Create payload for the API
      const payload = {
        records: updatedRecords,
        ...complianceData
      };
      
      // Save the updated data
      const serverResponse = await saveTrainingData(payload);
      
      // Display success message
      setSaveResponse({
        success: true,
        message: `Successfully added training record for ${record.employee}`,
      });
      
      // Reload data and close the form
      loadTrainingData();
      setShowAddForm(false);
    } catch (err) {
      console.error('Error adding training record:', err);
      setSaveResponse({
        success: false,
        message: `Error: ${err.message || 'Failed to add training record'}`,
      });
    }
  };

  // Handle update of a single training record
  const handleUpdateRecord = async (updatedRecord) => {
    try {
      const updatedRecords = trainingRecords.map(r => r._id === updatedRecord._id ? updatedRecord : r);
      const complianceData = generateComplianceData(updatedRecords);
      const payload = {
        records: updatedRecords,
        ...complianceData
      };
      const serverResponse = await saveTrainingData(payload);
      setSaveResponse({
        success: true,
        message: `Successfully updated training record for ${updatedRecord.employee}`,
      });
      loadTrainingData();
    } catch (err) {
      console.error('Error updating training record:', err);
      setSaveResponse({
        success: false,
        message: `Error: ${err.message || 'Failed to update training record'}`,
      });
    }
  };
  
  // Handle record archiving
  const handleArchive = async (id) => {
    if (!window.confirm('Are you sure you want to archive this training record? Archived records will be hidden from the main view but can be restored later.')) {
      return;
    }
    
    try {
      await archiveTrainingRecord(id);
      // Reload data after archiving
      loadTrainingData();
      setSaveResponse({
        success: true,
        message: 'Training record archived successfully',
      });
    } catch (err) {
      console.error('Error archiving training record:', err);
      setSaveResponse({
        success: false,
        message: `Error: ${err.message || 'Unknown error'}`,
      });
    }
  };
  
  // Handle record unarchiving
  const handleUnarchive = async (id) => {
    try {
      await unarchiveTrainingRecord(id);
      // Reload data after unarchiving
      loadTrainingData();
      setSaveResponse({
        success: true,
        message: 'Training record restored successfully',
      });
    } catch (err) {
      console.error('Error unarchiving training record:', err);
      setSaveResponse({
        success: false,
        message: `Error: ${err.message || 'Unknown error'}`,
      });
    }
  };
  
  // Format date for display
  const formatDate = (dateString) => {
    if (!dateString) return 'N/A';
    
    try {
      const date = new Date(dateString);
      return isNaN(date.getTime()) ? 'Invalid Date' : date.toLocaleDateString();
    } catch (e) {
      return 'Invalid Date';
    }
  };
  
  // Filter training records based on search input
  const filteredRecords = trainingRecords.filter(record => {
    if (!filter) return true;
    
    const searchValue = filter.toLowerCase();
    
    switch (filterBy) {
      case 'employee':
        return (record.employee || '').toLowerCase().includes(searchValue);
      case 'course':
        return (record.courseTitle || '').toLowerCase().includes(searchValue);
      case 'status':
        return (record.status || '').toLowerCase().includes(searchValue);
      case 'department':
        return (record.department || '').toLowerCase().includes(searchValue);
      default:
        return true;
    }
  });
  
  // Get status badge color based on status
  const getStatusBadgeColor = (status) => {
    switch (status?.toLowerCase()) {
      case 'completed':
        return 'bg-green-100 text-green-800';
      case 'expired':
        return 'bg-red-100 text-red-800';
      case 'in progress':
        return 'bg-yellow-100 text-yellow-800';
      default:
        return 'bg-gray-100 text-gray-800';
    }
  };
  
  return (
    <div className="p-6">
      <div className="flex justify-between items-center mb-6">
        <h1 className="text-2xl font-bold text-gray-800">Training Management</h1>
        <div className="space-x-3">
          <button
            onClick={() => { setShowAddForm(true); setShowUploader(false); }}
            className="bg-green-600 text-white px-4 py-2 rounded shadow hover:bg-green-700"
          >
            Add Single Record
          </button>
          <button
            onClick={() => { setShowUploader(!showUploader); setShowAddForm(false); }}
            className="bg-blue-600 text-white px-4 py-2 rounded shadow hover:bg-blue-700"
          >
            {showUploader ? 'Hide Uploader' : 'Upload Multiple Records'}
          </button>
          <Link to="/debug">
            <button className="bg-purple-600 text-white px-4 py-2 rounded shadow hover:bg-purple-700">
              Debug Tools
            </button>
          </Link>
          <Link to="/">
            <button className="bg-gray-600 text-white px-4 py-2 rounded shadow hover:bg-gray-700">
              Back to Dashboard
            </button>
          </Link>
        </div>
      </div>
      
      {/* Response Message */}
      {saveResponse && (
        <div className={`p-4 mb-4 rounded ${saveResponse.success ? 'bg-green-50 text-green-800' : 'bg-red-50 text-red-800'}`}>
          {saveResponse.message}
        </div>
      )}
      
      {/* Add Single Record Form */}
      {showAddForm && (
        <div className="mb-6">
          <SingleRecordForm 
            onRecordSubmit={handleAddRecord} 
            onUpdateRecord={handleUpdateRecord}
            onCancel={() => setShowAddForm(false)} 
          />
        </div>
      )}
      
      {/* CSV Uploader */}
      {showUploader && (
        <div className="mb-6">
          <TrainingUploader onDataProcessed={onDataProcessed} />
        </div>
      )}
      
      {/* Training Compliance Dashboard */}
      {!loading && trainingComplianceData && (
        <div className="mb-8">
          <TrainingComplianceDisplay trainingData={trainingComplianceData} />
        </div>
      )}
      
      <h2 className="text-xl font-semibold text-gray-800 mb-4 mt-8">Training Records</h2>
      
      {/* Search and Filter */}
      <div className="mb-6 flex flex-wrap gap-4">
        <div className="flex-1 min-w-[300px]">
          <label className="block text-sm font-medium text-gray-700 mb-1">Search</label>
          <input
            type="text"
            value={filter}
            onChange={(e) => setFilter(e.target.value)}
            placeholder="Search training records..."
            className="w-full px-3 py-2 border border-gray-300 rounded shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
          />
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Filter By</label>
          <select
            value={filterBy}
            onChange={(e) => setFilterBy(e.target.value)}
            className="px-3 py-2 border border-gray-300 rounded shadow-sm focus:outline-none focus:ring-blue-500 focus:border-blue-500"
          >
            <option value="employee">Employee</option>
            <option value="course">Course</option>
            <option value="status">Status</option>
            <option value="department">Department</option>
          </select>
        </div>
        <div>
          <label className="block text-sm font-medium text-gray-700 mb-1">Show Archived</label>
          <div className="flex items-center">
            <input
              type="checkbox"
              id="showArchived"
              checked={showArchived}
              onChange={(e) => setShowArchived(e.target.checked)}
              className="h-4 w-4 rounded border-gray-300 text-blue-600 focus:ring-blue-500"
            />
            <label htmlFor="showArchived" className="ml-2 block text-sm text-gray-700">
              {showArchived ? 'Showing archived records' : 'Archived records hidden'}
            </label>
          </div>
        </div>
        <div className="flex items-end">
          <button
            onClick={() => loadTrainingData()}
            className="px-3 py-2 bg-gray-100 text-gray-700 rounded shadow-sm hover:bg-gray-200"
            title="Refresh Data"
          >
            <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24" xmlns="http://www.w3.org/2000/svg">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M4 4v5h.582m15.356 2A8.001 8.001 0 004.582 9m0 0H9m11 11v-5h-.581m0 0a8.003 8.003 0 01-15.357-2m15.357 2H15"></path>
            </svg>
          </button>
        </div>
      </div>
      
      {/* Error State */}
      {error && (
        <div className="p-4 mb-4 bg-red-50 border border-red-200 rounded-md text-red-800">
          <div className="font-bold">Error:</div>
          <p>{error}</p>
        </div>
      )}
      
      {/* Loading State */}
      {loading && (
        <div className="text-center py-8">
          <div className="inline-block animate-spin rounded-full h-8 w-8 border-t-2 border-b-2 border-blue-500"></div>
          <p className="mt-2 text-gray-500">Loading training records...</p>
        </div>
      )}
      
      {/* Empty State */}
      {!loading && filteredRecords.length === 0 && (
        <div className="text-center py-8 bg-white rounded shadow-md">
          <svg className="mx-auto h-12 w-12 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
            <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M9 5H7a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2V7a2 2 0 00-2-2h-2M9 5a2 2 0 002 2h2a2 2 0 002-2M9 5a2 2 0 012-2h2a2 2 0 012 2"></path>
          </svg>
          <h3 className="mt-2 text-sm font-medium text-gray-900">No Training Records</h3>
          <p className="mt-1 text-sm text-gray-500">
            {filter ? 'No records match your search criteria.' : 'Get started by uploading training data.'}
          </p>
          <div className="mt-6 flex justify-center space-x-3">
            <button
              type="button"
              onClick={() => setShowAddForm(true)}
              className="inline-flex items-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-green-600 hover:bg-green-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-green-500"
            >
              <svg className="-ml-1 mr-2 h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M12 6v6m0 0v6m0-6h6m-6 0H6"></path>
              </svg>
              Add Single Record
            </button>
            <button
              type="button"
              onClick={() => setShowUploader(true)}
              className="inline-flex items-center px-4 py-2 border border-transparent shadow-sm text-sm font-medium rounded-md text-white bg-blue-600 hover:bg-blue-700 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-blue-500"
            >
              <svg className="-ml-1 mr-2 h-5 w-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                <path strokeLinecap="round" strokeLinejoin="round" strokeWidth="2" d="M7 16a4 4 0 01-.88-7.903A5 5 0 1115.9 6L16 6a5 5 0 011 9.9M15 13l-3-3m0 0l-3 3m3-3v12"></path>
              </svg>
              Upload Multiple Records
            </button>
          </div>
        </div>
      )}
      
      {/* Data Table */}
      {!loading && filteredRecords.length > 0 && (
        <div className="overflow-x-auto rounded-lg shadow">
          <table className="min-w-full divide-y divide-gray-200 bg-white">
            <thead className="bg-gray-50">
              <tr>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Employee</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Course</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Status</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Completion Date</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Expiry Date</th>
                <th scope="col" className="px-6 py-3 text-left text-xs font-medium text-gray-500 uppercase tracking-wider">Department</th>
                <th scope="col" className="px-6 py-3 text-right text-xs font-medium text-gray-500 uppercase tracking-wider">Actions</th>
              </tr>
            </thead>
            <tbody className="bg-white divide-y divide-gray-200">
              {filteredRecords.map((record, index) => (
                <tr 
                  key={record._id || index} 
                  className={`${record.archived ? 'bg-gray-100 hover:bg-gray-200 text-gray-500' : 'hover:bg-gray-50'}`}
                >
                  <td className="px-6 py-4 whitespace-nowrap">
                    <div className="flex items-center">
                      <div className="text-sm font-medium text-gray-900">{record.employee}</div>
                      {record.archived && (
                        <span className="ml-2 px-2 inline-flex text-xs leading-5 font-semibold rounded-full bg-gray-100 text-gray-800">
                          Archived
                        </span>
                      )}
                    </div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="text-sm text-gray-900">{record.courseTitle}</div>
                    {record.courseType && (
                      <div className="text-xs text-gray-500">{record.courseType}</div>
                    )}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap">
                    <span className={`px-2 inline-flex text-xs leading-5 font-semibold rounded-full ${getStatusBadgeColor(record.status)}`}>
                      {record.status || 'Unknown'}
                    </span>
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {formatDate(record.completionDate)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {formatDate(record.expiryDate)}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-sm text-gray-500">
                    {record.department || '-'}
                  </td>
                  <td className="px-6 py-4 whitespace-nowrap text-right text-sm font-medium space-x-3">
                    {!record.archived && (
                      <button
                        onClick={() => {
                          setShowAddForm(true);
                          setShowUploader(false);
                          setTimeout(() => {
                            document.dispatchEvent(new CustomEvent('edit-record', { detail: record }));
                          }, 0);
                        }}
                        className="text-blue-600 hover:text-blue-900"
                      >
                        Edit
                      </button>
                    )}
                    {record.archived ? (
                      <button
                        onClick={() => handleUnarchive(record._id)}
                        className="text-green-600 hover:text-green-900"
                      >
                        Restore
                      </button>
                    ) : (
                      <button
                        onClick={() => handleArchive(record._id)}
                        className="text-amber-600 hover:text-amber-900"
                      >
                        Archive
                      </button>
                    )}
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
          
          <div className="bg-gray-50 px-4 py-3 text-right">
            <span className="text-sm text-gray-700">
              Showing <span className="font-medium">{filteredRecords.length}</span> of <span className="font-medium">{trainingRecords.length}</span> records
            </span>
          </div>
        </div>
      )}
    </div>
  );
}

